const $=id=>document.getElementById(id);let apiKey='',video=null,busy=false,demoMode=false,segments=[],config=null,activeExport=null;
const status=t=>$('status').textContent=t;
const time=n=>Math.floor(n/60).toString().padStart(2,'0')+':'+Math.floor(n%60).toString().padStart(2,'0');
async function request(path,body,method='POST'){
 let r;try{r=await fetch(path,{method,headers:body instanceof FormData?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:body instanceof FormData?body:JSON.stringify(body)})}catch{throw Error('Não foi possível conectar ao servidor. Verifique sua conexão e tente novamente.')}
 let result;try{result=await r.json()}catch{
  if(r.status===403)throw Error('O servidor bloqueou esta solicitação (HTTP 403). A configuração de origem do site precisa ser corrigida.');
  if(r.status===401)throw Error('Seu acesso expirou. Atualize a página e entre novamente.');
  throw Error('O servidor retornou uma resposta inesperada (HTTP '+r.status+'). Tente novamente ou verifique os logs da hospedagem.');
 }
 if(!r.ok)throw Error(typeof result.detail==='string'?result.detail:'Revise os dados enviados.');return result;
}
async function waitJob(id){for(;;){await new Promise(r=>setTimeout(r,1200));const job=await request('/api/jobs/'+id,undefined,'GET');status(job.progress||'Processando…');if(job.status==='done')return job.result;if(job.status==='failed')throw Error(job.error||'O processamento falhou.')}}
function lock(value){busy=value;for(const id of ['generate','importlink','editcaptions'])$(id).disabled=value||(id==='editcaptions'&&!segments.length);$('file').disabled=value;}
for(const id of ['settings','settings2'])$(id).onclick=()=>$('modal').showModal();
$('savekey').onclick=()=>{const value=$('key').value.trim();if(!value.startsWith('sk-')){$('keyerror').textContent='Insira uma chave OpenAI válida.';return}apiKey=value;$('key').value='';$('connection').style.color='#6aa34c';$('settings2').firstChild.textContent='IA conectada ';$('modal').close();status('Chave disponível para esta sessão. Será validada na análise.');};
function setVideo(value){video=value;segments=[];demoMode=false;$('filename').textContent=video.filename;$('duration').textContent=time(video.duration);$('selected').hidden=false;$('results').hidden=true;$('editcaptions').disabled=true;status('Vídeo pronto para analisar.');}
async function choose(file){if(busy||!file)return;if(file.size>1024*1024*1024)return status('O limite é 1 GB.');lock(true);try{status('Enviando vídeo ao servidor…');const form=new FormData();form.append('file',file);setVideo(await request('/api/upload',form));}catch(e){status(e.message)}finally{lock(false)}}
$('file').onchange=e=>choose(e.target.files[0]);const drop=$('drop');drop.ondragover=e=>{e.preventDefault();drop.classList.add('drag')};drop.ondragleave=()=>drop.classList.remove('drag');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('drag');choose(e.dataTransfer.files[0])};
$('importlink').onclick=async()=>{if(busy)return;const url=$('link').value.trim();if(!url)return status('Cole o link público de um vídeo ou clip.');lock(true);try{status('Iniciando importação…');const job=await request('/api/import',{url});setVideo(await waitJob(job.job_id));}catch(e){status(e.message)}finally{lock(false)}};
$('generate').onclick=async()=>{if(busy)return;if(!video)return status('Envie um arquivo ou importe um link antes de analisar.');if(!apiKey&&!config?.server_ai){$('modal').showModal();return}lock(true);try{status('Iniciando análise pela fala…');const job=await request('/api/analyze',{video_id:video.video_id,maximum:Number($('length').value),api_key:apiKey});const result=await waitJob(job.job_id);segments=result.segments;demoMode=false;render(result.clips);status(result.clips.length?'Cortes sugeridos. Revise a fala, os tempos e as legendas antes de exportar.':'Nenhum corte completo encontrado. As legendas estão disponíveis para revisão.');}catch(e){status(e.message)}finally{lock(false)}};
function render(clips){$('cards').replaceChildren();$('demoBadge').textContent=demoMode?'· EXEMPLO FICTÍCIO':'';$('results').hidden=false;clips.forEach((clip,i)=>{const card=document.createElement('article');card.className='card';const visual=document.createElement(demoMode?'div':'video');if(demoMode){visual.className='placeholder';visual.textContent='✦'}else{visual.src=video.url;visual.controls=true;visual.playsInline=true;visual.preload='metadata';visual.onloadedmetadata=()=>visual.currentTime=clip.start;visual.ontimeupdate=()=>{if(visual.currentTime>=clip.end&&!visual.paused)visual.pause()};visual.onplay=()=>{if(visual.currentTime<clip.start||visual.currentTime>=clip.end)visual.currentTime=clip.start}}card.append(visual);const tag=document.createElement('p');tag.className='score';tag.textContent='CORTE '+String(i+1).padStart(2,'0')+' · '+time(clip.end-clip.start);card.append(tag);const h=document.createElement('h3');h.textContent=clip.title;card.append(h);const p=document.createElement('p');p.textContent=clip.reason;card.append(p);const times=document.createElement('div');times.className='times';for(const [prop,label] of [['start','Início (segundos)'],['end','Fim (segundos)']]){const l=document.createElement('label');l.textContent=label;const input=document.createElement('input');input.type='number';input.min=0;input.max=video?.duration||1000;input.step=.1;input.value=clip[prop];input.disabled=demoMode;input.onchange=()=>clip[prop]=Number(input.value);l.append(input);times.append(l)}card.append(times);const b=document.createElement('button');b.className='primary';b.textContent=demoMode?'Exemplo · envie seu vídeo':'↓ Gerar MP4';b.disabled=demoMode;const actions=document.createElement('div');actions.className='actions';b.onclick=()=>exportClip(clip,b,actions);card.append(b,actions);$('cards').append(card)});$('results').scrollIntoView({behavior:'smooth',block:'start'})}
async function exportClip(clip,button,actions){if(busy)return status('Aguarde o processamento atual.');if(!(clip.start>=0&&clip.end>clip.start&&clip.end<=video.duration))return status('Revise os tempos do corte.');lock(true);button.disabled=true;try{status('Preparando MP4…');const job=await request('/api/render',{video_id:video.video_id,start:clip.start,end:clip.end,format:$('format').value,subtitles:$('burnsubtitles').checked,title:clip.title,segments});const result=await waitJob(job.job_id);actions.replaceChildren();const a=document.createElement('a');a.href=result.url;a.textContent='↓ Baixar MP4';actions.append(a);if(result.subtitles_url){const sub=document.createElement('a');sub.href=result.subtitles_url;sub.textContent='↓ Legendas SRT';actions.append(sub)}const schedule=document.createElement('button');schedule.className='subtle';schedule.textContent='◷ Agendar';schedule.onclick=()=>openSchedule(result.export_id,clip.title);actions.append(schedule);status('MP4 pronto, com recorte central no formato escolhido. Baixe ou agende o corte.');}catch(e){status(e.message)}finally{lock(false);button.disabled=false;button.textContent='↓ Gerar MP4'}}
$('editcaptions').onclick=()=>{if(!segments.length||busy)return;$('captionrows').replaceChildren();segments.forEach((segment,i)=>{const row=document.createElement('div');row.className='captionrow';const timeLabel=document.createElement('small');timeLabel.textContent=time(segment.start)+' – '+time(segment.end);const text=document.createElement('textarea');text.value=segment.text;text.dataset.index=i;text.maxLength=2000;row.append(timeLabel,text);$('captionrows').append(row)});$('captionmodal').showModal()};$('savecaptions').onclick=()=>{for(const input of $('captionrows').querySelectorAll('textarea'))segments[Number(input.dataset.index)].text=input.value;$('captionmodal').close();status('Legendas revisadas. Gere novamente os cortes para aplicar as alterações.');};
async function refreshSocial(){try{config=await request('/api/config',undefined,'GET');if(config.server_ai){$('connection').style.color='#6aa34c';$('settings2').firstChild.textContent='IA no servidor ';}$('accounts').replaceChildren();for(const platform of config.platforms){const card=document.createElement('article');card.className='account';const h=document.createElement('h3');h.textContent=platform.name;card.append(h);const entries=config.accounts.filter(a=>a.platform===platform.platform);const p=document.createElement('p');p.textContent=entries.length?entries.map(a=>a.name).join(', '):platform.message;card.append(p);const button=document.createElement('button');button.className='subtle';button.textContent='Conectar conta';button.disabled=!platform.configured;button.onclick=async()=>{try{const result=await request('/api/oauth/'+platform.platform+'/start',{});window.location.assign(result.url)}catch(e){status(e.message)}};card.append(button);for(const account of entries){const remove=document.createElement('button');remove.className='subtle';remove.textContent='Desconectar '+account.name;remove.onclick=async()=>{try{await request('/api/accounts/'+account.id,undefined,'DELETE');await refreshSocial()}catch(e){status(e.message)}};card.append(remove)}$('accounts').append(card)}await refreshSchedules()}catch(e){status('Backend indisponível. Execute o servidor conforme o README para importar, analisar e exportar. A demonstração continua disponível.')}}
const labels={scheduled:'Agendado',publishing:'Publicando',published:'Publicação enviada',cancelled:'Cancelado',uncertain:'Verificação necessária'};
async function refreshSchedules(){const items=await request('/api/schedules',undefined,'GET');$('schedules').replaceChildren();if(!items.length){const p=document.createElement('p');p.className='note';p.textContent='Sua agenda está vazia. Gere um MP4 e escolha Agendar.';$('schedules').append(p)}for(const item of items){const row=document.createElement('div');row.className='scheduleitem';const b=document.createElement('b');b.textContent=item.title+' · '+(item.platform||'Conta desconectada');const p=document.createElement('p');p.textContent=new Date(item.due*1000).toLocaleString()+' · '+(labels[item.status]||item.status)+(item.error?' · '+item.error:'');row.append(b,p);if(item.status==='scheduled'){const cancel=document.createElement('button');cancel.className='subtle';cancel.textContent='Cancelar';cancel.onclick=async()=>{try{await request('/api/schedules/'+item.id,undefined,'DELETE');await refreshSchedules()}catch(e){status(e.message)}};row.append(cancel)}$('schedules').append(row)}}
async function openSchedule(exportId,title){await refreshSocial();if(!config?.accounts.length){status('Conecte uma conta oficial para agendar. Faltam as credenciais do aplicativo no servidor.');$('socialsection').scrollIntoView({behavior:'smooth'});return}activeExport=exportId;$('scheduleaccount').replaceChildren();for(const account of config.accounts){const option=document.createElement('option');option.value=account.id;option.textContent=account.platform+' · '+account.name;$('scheduleaccount').append(option)}$('scheduletitle').value=title.slice(0,100);$('schedulecaption').value=title;$('scheduleconsent').checked=false;$('scheduleerror').textContent='';const future=new Date(Date.now()+3600000);future.setMinutes(future.getMinutes()-future.getTimezoneOffset());$('schedulewhen').value=future.toISOString().slice(0,16);$('schedulemodal').showModal()}
$('saveschedule').onclick=async()=>{const button=$('saveschedule');if(button.disabled)return;button.disabled=true;try{const date=new Date($('schedulewhen').value);if(!Number.isFinite(date.getTime()))throw Error('Escolha uma data e hora.');await request('/api/schedules',{export_id:activeExport,account_id:$('scheduleaccount').value,title:$('scheduletitle').value,caption:$('schedulecaption').value,when:date.toISOString(),consent:$('scheduleconsent').checked});$('schedulemodal').close();await refreshSchedules();status('Publicação agendada. Mantenha o servidor ligado no horário escolhido.')}catch(e){$('scheduleerror').textContent=e.message}finally{button.disabled=false}};
$('socialnav').onclick=()=>$('socialsection').scrollIntoView({behavior:'smooth'});$('refreshsocial').onclick=refreshSocial;
$('demo').onclick=()=>{if(busy)return;demoMode=true;render([{title:'O começo de uma boa história',reason:'Exemplo fictício de um trecho com gancho inicial e uma ideia completa.',start:12,end:42},{title:'Uma mudança de perspectiva',reason:'Exemplo fictício de uma descoberta que desperta curiosidade.',start:64,end:109},{title:'O conselho que fica',reason:'Exemplo fictício de uma dica prática e direta.',start:132,end:170}]);status('Demonstração. Nenhum vídeo foi analisado.')};$('clear').onclick=()=>{if(!busy){$('results').hidden=true;$('cards').replaceChildren();status('Resultados limpos.')}};$('home').onclick=()=>window.scrollTo({top:0,behavior:'smooth'});window.addEventListener('beforeunload',e=>{if(busy){e.preventDefault();e.returnValue=''}});refreshSocial();setInterval(()=>{if(config&&!document.hidden)refreshSchedules().catch(()=>{})},30000);
